CREATE TABLE "outbox" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"aggregate_type" text,
	"aggregate_id" uuid,
	"type" text NOT NULL,
	"payload" jsonb NOT NULL,
	"dedupe_key" text,
	"status" text DEFAULT 'pending' NOT NULL,
	"attempts" integer DEFAULT 0 NOT NULL,
	"available_at" timestamp with time zone DEFAULT now() NOT NULL,
	"dispatched_at" timestamp with time zone,
	"last_error" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "outbox_type_check" CHECK ("outbox"."type" IN ('audit.event', 'notify.send', 'temporal.signal')),
	CONSTRAINT "outbox_status_check" CHECK ("outbox"."status" IN ('pending', 'dispatched', 'failed')),
	CONSTRAINT "outbox_payload_object_check" CHECK (jsonb_typeof("outbox"."payload") = 'object'),
	CONSTRAINT "outbox_payload_size_check" CHECK (octet_length("outbox"."payload"::text) <= 65536),
	CONSTRAINT "outbox_dedupe_key_check" CHECK ("outbox"."dedupe_key" IS NULL OR length("outbox"."dedupe_key") BETWEEN 1 AND 255),
	CONSTRAINT "outbox_attempts_check" CHECK ("outbox"."attempts" >= 0),
	CONSTRAINT "outbox_dispatched_check" CHECK ("outbox"."status" <> 'dispatched' OR "outbox"."dispatched_at" IS NOT NULL)
);
