REVOKE ALL ON "outbox" FROM PUBLIC;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON "outbox" TO bw_app;--> statement-breakpoint
-- Keeps updated_at in step with the relay's status changes (bw_set_updated_at: 0002_column_mixins).
